var subtractProductAndSum = function(n) {
    let product = 1;
    let total = 0;

    // Extract digits one at a time from least significant to most significant
    while (n > 0) {
        // Get the last digit
        const digit = n % 10;

        // Accumulate product and sum
        product *= digit;
        total += digit;

        // Remove the last digit
        n = Math.floor(n / 10);
    }

    return product - total;
};
